    seen = {(player, frozenset(boxes))}
    queue = deque([(player, frozenset(boxes), 0)])
    while queue:
        p, b, d = queue.popleft()
        for a in ACTIONS:
            np, nb, word = step(pos, a)
            if word == 'blocked':
                continue
            nb = frozenset(nb)
            key = (np, nb)
            if key in seen:
                continue
            if solved(np):
                return d + 1
            seen.add(key)
            queue.append((np, nb, d + 1))
